import { useState, type FormEvent } from 'react';
import type { OwnPerson } from '@fmv/contracts';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';

// Presentation generated by the sandboxed OpenCode GLM worker; reviewed locally.
export function PersonPanel({
  person,
  busy,
  error,
  onCreate,
}: {
  person: OwnPerson | null;
  busy: boolean;
  error?: string;
  onCreate: (displayName: string) => void;
}) {
  const [displayName, setDisplayName] = useState('');
  const trimmed = displayName.trim();
  const canSubmit = trimmed.length > 0 && !busy;
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (canSubmit) onCreate(trimmed);
  };
  return (
    <section
      className="person-panel"
      aria-labelledby="person-title"
      aria-busy={busy}
    >
      <h2 id="person-title">
        {person ? 'Your personal profile' : 'Create your personal profile'}
      </h2>
      {error && (
        <p className="auth-panel__error" role="alert">
          {error}
        </p>
      )}
      {person ? (
        <>
          <p>{person.displayName}</p>
          <dl>
            <dt>Person ID</dt>
            <dd>{person.id}</dd>
          </dl>
          <p>Medical record permissions are configured separately.</p>
        </>
      ) : (
        <>
          <p>This creates your own profile only.</p>
          <form onSubmit={handleSubmit}>
            <label htmlFor="display-name">Your name</label>
            <Input
              id="display-name"
              name="displayName"
              type="text"
              value={displayName}
              maxLength={100}
              required
              autoComplete="name"
              disabled={busy}
              onChange={(event) => setDisplayName(event.target.value)}
            />
            <Button type="submit" disabled={!canSubmit}>
              {busy ? 'Creating profile…' : 'Create my profile'}
            </Button>
          </form>
        </>
      )}
    </section>
  );
}
